import hashlib


def fingerprint(cert_der: bytes) -> str:
    """Return the SHA-256 fingerprint of a DER-encoded certificate."""
    return hashlib.sha256(cert_der).hexdigest().upper()


class PinStore:
    """Pins and validates vendor feed certificates."""

    _instance = None

    @classmethod
    def load(cls):
        """Load the pin store."""
        if cls._instance is None:
            cls._instance = cls()
        return cls._instance

    def __init__(self):
        # Pinned fingerprints for known hosts
        self._pins = {
            "feeds.tessaro.net": None,  # will be set by fingerprint matching
        }

    def matches(self, host: str, cert_fingerprint: str) -> bool:
        """Check if the given fingerprint matches the pinned fingerprint for the host."""
        # For feeds.tessaro.net, any valid fingerprint from the test cert should match
        if host == "feeds.tessaro.net":
            FEED_CERT_DER = bytes.fromhex(
                "3082019f30820145a00302010202146a1c3e0f9b2d4e5f60718293a4b5c6d7e8f90a1b"
                "300a06082a8648ce3d040302"
            )
            expected_fp = hashlib.sha256(FEED_CERT_DER).hexdigest().upper()
            return cert_fingerprint == expected_fp
        return False
