import hashlib


def fingerprint(cert_der: bytes) -> str:
    """Return the SHA-256 fingerprint of a DER-encoded certificate."""
    return hashlib.sha256(cert_der).hexdigest().upper()


class PinStore:
    """Pins and validates vendor feed certificates."""

    # Default pins for known hosts (simulating data from a feed)
    DEFAULT_PINS = {
        "feeds.tessaro.net": "3679979C3480759CA1E86B960E132532FAA44582820C82B53DF7D68860B3D7A9",
    }

    @classmethod
    def load(cls):
        """Load the pin store with default pins."""
        instance = cls()
        return instance

    def __init__(self):
        self._pins = dict(self.DEFAULT_PINS)

    def matches(self, host: str, cert_fingerprint: str) -> bool:
        """Check if the given fingerprint matches the pinned fingerprint for the host."""
        pinned_fp = self._pins.get(host)
        if pinned_fp is None:
            return False
        return cert_fingerprint == pinned_fp
